                    comments.stream().map(CommentView::of).toList(), c.getEditedBy(), c.getBatch(),
                    lines.stream().map(LineView::of).toList(), c.getAdded() != null ? c.getAdded() : id,
                    c.getReviewOn(), c.isWaived(), c.getReceiptProofs(), c.getPhotoProofs());
        }

